import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.BPFk9-tb.js";const _=JSON.parse('{"title":"写作课作业-112","description":"","frontmatter":{"date":"2021-03-07T14:29:43","title":"写作课作业-112","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/112.md","filePath":"posts/homework/112.md"}'),h={name:"posts/homework/112.md"};function l(i,e,n,s,p,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<blockquote><p>《区块链小白书》之《比特币 8.比特币凭什么涨啊涨》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>比特币（BTC）还有很大的上涨空间。</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>把比特币（BTC）理解成比特币银行（Bitcoin）发行的股票，比特币银行的的核心业务是：发行和记账。它的价值取决于多少人认同它、使用它。截止2019年，全球使用比特币的人数不超过3000万，相对于人口数量，比例很小，所以还有很大的上涨空间。</p><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>公司股票因为公司不断创造价值而升值。通过<a href="https://bitinfocharts.com/top-100-richest-bitcoin-addresses.html" target="_blank" rel="noreferrer">bitinfocharts</a>,当前（2021-03-01）持币0-0.001的地址数是18523095个，占比50.74%，计算得到的总地址数是36505902。如果按<a href="https://www.sohu.com/a/408240948_100217347" target="_blank" rel="noreferrer">数据：2155个地址持有779万枚BTC，占总数42.26%</a> 发布的时间（2020-07-17）的截图计算的话，地址总数是30485383。也就是认同和使用比特币（记账）的人越来越多，增长的速度也越来越快。</p><p>持有0.1个比特币就可以超过90%的地址（人），持有1个以上的比特币就超过97%的地址（人）。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',17)])])}const w=a(h,[["render",l]]);export{_ as __pageData,w as default};
